import { Group, PlaneGeometry, MeshBasicNodeMaterial, Mesh } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Create plane geometry with aspect ratio 512:320
  const geometry = new PlaneGeometry(1.6, 1);

  // Create basic material
  const material = new MeshBasicNodeMaterial({ map: texture });

  // Create mesh
  const mesh = new Mesh(geometry, material);

  // Apply scene position
  const pos = config.scenePosition || { x: 0, y: 0, z: 0 };
  mesh.position.set(pos.x, pos.y, pos.z);

  if (pos.rotationXYZ) {
    mesh.rotation.order = 'XYZ';
    mesh.rotation.set(pos.rotationXYZ[0], pos.rotationXYZ[1], pos.rotationXYZ[2]);
  }

  if (pos.scaleXYZ) {
    mesh.scale.set(pos.scaleXYZ[0], pos.scaleXYZ[1], pos.scaleXYZ[2]);
  }

  group.add(mesh);

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Handlers
  group.userData.handlers = {};

  return group;
}
